/*
 * A320926  Concatenation of successive segments generated by the morphism {0
 *          -> {0, 0, 1}, 1 -> {0}}, starting with 0.
 * https://oeis.org/A320926
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 8885, u16 n <= 8885, u32 n <= 8885, u64 n <= 8885,
 *            u128 n <= 8885, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computation of A320926.  The sequence is the infinite
 * concatenation of successive segments produced by the
 * morphism τ:
 *     0 → {0,0,1}
 *     1 → {0}
 * starting from the one‑element segment {0}.
 * The function returns the n‑th term (1‑based) of that
 * infinite binary word.  It uses a simple iterative
 * construction of the required segment; the segments
 * are stored as bytes to keep the code type‑independent
 * (seq_t may be an arbitrary‑precision integer class).
 */
#include <stdlib.h>

seq_t a(idx_t n)
{
    if (n == 0) {                 /* offset is 1, but guard against 0 */
        return (seq_t)0;
    }

    idx_t cumulative = 0;    /* total length of all previous segments */
    idx_t seg_len = 1;       /* length of the current segment */

    /* initial segment {0} */
    uint8_t *seg = (uint8_t *)malloc(seg_len);
    if (!seg) {                /* allocation failure – return 0 */
        return (seq_t)0;
    }
    seg[0] = 0;

    /* generate successive segments until the n-th term is in the
     * current segment.  cum + seg_len is the total length after
     * adding the current segment; if that is still < n we need the
     * next segment.                                                     */
    while (cumulative + seg_len < n) {
        cumulative += seg_len;

        /* The maximum possible new length is 3*seg_len (all zeros)
           plus one (for a single one, but this never exceeds 3*len). */
        uint8_t *new_seg = (uint8_t *)malloc(seg_len * 3 + 1);
        if (!new_seg) {
            free(seg);
            return (seq_t)0;
        }

        idx_t new_len = 0;
        for (idx_t i = 0; i < seg_len; ++i) {
            if (seg[i] == 0) {
                new_seg[new_len++] = 0;
                new_seg[new_len++] = 0;
                new_seg[new_len++] = 1;
            } else {                /* seg[i] == 1 */
                new_seg[new_len++] = 0;
            }
        }

        free(seg);
        seg = new_seg;
        seg_len = new_len;
    }

    /* n lies in the current segment; compute offset within it. */
    idx_t offset = n - cumulative - 1;   /* 0‑based */
    seq_t result = (seq_t)seg[offset];

    free(seg);
    return result;
}
